<?php
require_once 'config.php';requirePost();$user=requireRole('admin','supervisor');
$mode=$_POST['scope']??'mine';$filterSup=trim((string)($_POST['filter_supervisor']??''));$showOther=$user['role']==='admin'||hasPermission('can_view_other_teams');
$where='';$p=[];
if($user['role']==='supervisor'){if(!$showOther||$mode==='mine'){$where=' AND r.supervisor_username=?';$p[]=$user['username'];}else{$where=' AND r.supervisor_username<>?';$p[]=$user['username'];if($filterSup!==''){$where.=' AND r.supervisor_username=?';$p[]=$filterSup;}}}
$sql="SELECT r.id,r.expert_username,e.display_name expert_name,r.supervisor_username,u.display_name supervisor_name,r.status,r.request_type,r.reason,r.requested_at,r.approved_at,r.duration_minutes,r.overtime_seconds,UNIX_TIMESTAMP(r.approved_at) approved_ts FROM rest_requests r LEFT JOIN experts e ON e.username=r.expert_username LEFT JOIN users u ON u.username=r.supervisor_username WHERE r.status='pending' $where ORDER BY r.requested_at ASC,r.id ASC";$st=$pdo->prepare($sql);$st->execute($p);$pending=$st->fetchAll();
$sql="SELECT r.id,r.expert_username,e.display_name expert_name,r.supervisor_username,u.display_name supervisor_name,r.status,r.request_type,r.approved_at,r.duration_minutes,r.overtime_seconds,UNIX_TIMESTAMP(r.approved_at) approved_ts FROM rest_requests r LEFT JOIN experts e ON e.username=r.expert_username LEFT JOIN users u ON u.username=r.supervisor_username WHERE r.status='approved' $where ORDER BY r.approved_at ASC";$st=$pdo->prepare($sql);$st->execute($p);$active=$st->fetchAll();
$statsSql="SELECT COUNT(*) total,SUM(status='completed') completed,SUM(status='overtime') overtime FROM rest_requests r WHERE DATE(r.created_at)=CURDATE()".$where;$st=$pdo->prepare($statsSql);$st->execute($p);$s=$st->fetch();
foreach($pending as &$r)$r['requested_at']=toJalaliFa($r['requested_at']);unset($r);foreach($active as &$r)$r['approved_at']=toJalaliFa($r['approved_at']);unset($r);
$st=$pdo->query("SELECT e.username,e.display_name,e.supervisor_username,u.display_name supervisor_name,e.rest_login_count,e.daily_rest_limit,e.last_rest_login_date FROM experts e LEFT JOIN users u ON u.username=e.supervisor_username ORDER BY u.display_name,e.display_name");$experts=$st->fetchAll();
$todayOver=[];$oq=$pdo->query("SELECT expert_username,MAX(overtime_seconds) overtime_seconds FROM overtime_alerts WHERE alert_date=CURDATE() GROUP BY expert_username");foreach($oq->fetchAll() as $or)$todayOver[$or['expert_username']]=(int)$or['overtime_seconds'];
$todayCompletedOver=[];$oq=$pdo->query("SELECT expert_username,MAX(overtime_seconds) overtime_seconds FROM rest_requests WHERE DATE(created_at)=CURDATE() AND overtime_seconds>0 GROUP BY expert_username");foreach($oq->fetchAll() as $or)$todayCompletedOver[$or['expert_username']]=(int)$or['overtime_seconds'];
foreach($experts as &$e){$e['rest_login_count']=($e['last_rest_login_date']===date('Y-m-d'))?(int)$e['rest_login_count']:0;$e['daily_rest_count']=$e['rest_login_count'];$e['currently_resting']=false;$e['over_limit']=false;$e['over_limit_seconds']=0;$e['over_limit_reason']='';}unset($e);
$pendingExperts=[];$q=$pdo->query("SELECT DISTINCT expert_username FROM rest_requests WHERE status='pending'");foreach($q->fetchAll(PDO::FETCH_COLUMN) as $pu)$pendingExperts[$pu]=true;foreach($experts as &$e)$e['pending_request']=isset($pendingExperts[$e['username']]);unset($e);
foreach($experts as &$e){foreach($active as $a){if($a['expert_username']===$e['username']){$elapsed=max(0,time()-(int)($a['approved_ts']??strtotime($a['approved_at'])));$allowed=max(0,(int)$a['duration_minutes']*60);if($elapsed>=$allowed){$e['currently_resting']=false;$e['over_limit']=true;$e['over_limit_seconds']=max(0,$elapsed-$allowed);$e['over_limit_reason']='استراحت فعلی از زمان مجاز عبور کرده است.';}else{$e['currently_resting']=true;$e['over_limit']=false;$e['over_limit_seconds']=0;$e['over_limit_reason']='';}break;}}}unset($e);
$st=$pdo->query("SELECT username,display_name FROM users WHERE role='supervisor' ORDER BY display_name");$supervisors=$st->fetchAll();
$overLimitCount=0;foreach($experts as $ve){$inScope=true;if($user['role']==='supervisor'){$inScope=($mode==='mine')?($ve['supervisor_username']===$user['username']):($ve['supervisor_username']!==$user['username']);if($filterSup!=='')$inScope=$inScope&&($ve['supervisor_username']===$filterSup);}if($inScope&&$ve['over_limit'])$overLimitCount++;}
jsonResponse(['success'=>true,'pending'=>$pending,'active'=>$active,'experts'=>$experts,'supervisors'=>$supervisors,'stats'=>['total'=>(int)($s['total']??0),'pending'=>count($pending),'active'=>count($active),'completed'=>(int)($s['completed']??0),'overtime'=>(int)($s['overtime']??0),'over_limit_count'=>$overLimitCount]]);
